"""Implementation of actions for the Register New Patient UI in the Mosaiq application"""

from .objects.mosaiq_register_patient_objects import PatientRegObjects
from .objects.mosaiq_d_and_i_objects import DandI
from interops.libraries.squish_actions import CommonActions
from interops.libraries.desktop import decorators as deco
from interops.libraries.squish_actions.constants import MOSAIQ_APP_NAME

def __find_new_patient_reg_window() -> bool:
    """Searches for the main New Patient Registration window within the Register Patient workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the new_patient_reg.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PatientRegObjects.newPatientReg_Window) is not None else False

def __find_no_duplicate_patient_dialog() -> bool:
    """Searches for the No Duplicate Patient dialog within the Register Patient workflow. Returns True if successfully located.

    -> Hidden function that should not be used outside the context of the new_patient_reg.py file context!

    :return: True or False
    :rtype: bool
    """
    return True if CommonActions.find_object(PatientRegObjects.newPatientReg_NoDuplicate_Dialog_Window) is not None else False

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def typeText_in_patient_last_name(lastName: str) -> None:
    """Locates the main New Patient Registration window > types a given lastName string into the Demographics last name text box.

    :param str lastName: Patients Last Name string to be typed into the Demographics last name text box
    """
    if __find_new_patient_reg_window():
        CommonActions.type_in_textfield(PatientRegObjects.newPatientReg_Demographics_NameTab_Last, lastName)

