@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def open_select_attending_physician_window() -> None:
    """Locates the main New Patient Registration window > clicks the Open Attending Physician UI button >
    waits for Attending Physician UI to appear.
    """
    if __find_new_patient_reg_window():
        CommonActions.left_click_object(PatientRegObjects.newPatientReg_Attending_Physician_button)
        CommonActions.find_object(PatientRegObjects.newPatientReg_SelectPhysician_Window)

@deco.set_separate_app_context(MOSAIQ_APP_NAME)
def select_physician_from_entire_list(physicianName: str) -> None:
    """Grabs all the child objects from the Attending Physician data grid > locates the child row object by the given physicianName string >
    locates the Name cell of the found row object > then performs a primary mouse button double click on that object.

    :param str physicianName: Physician Name string to be located within the Attending Physician data grid
    """
    gridData_children = CommonActions.get_child_objects(PatientRegObjects.newPatientReg_SelectPhysician_StaffGrid_data)
    physician_row = CommonActions.get_child_object_by_value(gridData_children, physicianName)
    name_cell = CommonActions.get_child_object_by_value(CommonActions.get_child_objects(physician_row), physicianName)
    CommonActions.double_click_object(name_cell)

